#include <iostream>
#include <string>
#include <array>

int main() {
    std::string s, t;
    std::cin >> s >> t;

    std::array<int, 26> count{};

    for (char c : s) {
        ++count[c - 'a'];
    }

    for (char c : t) {
        --count[c - 'a'];
    }

    for (int x : count) {
        if (x != 0) {
            std::cout << 0 << '\n';
            return 0;
        }
    }

    std::cout << 1 << '\n';
    return 0;
}
